function select_subdistrict(code,id,district){
  $('#'+id).empty().append('<option value="NULL">เลือกตำบล</option>');
  $.each(subdistrict,function(index,item){
    if(item.district_id==district){
        $('#'+id).append('<option value="'+ item.code +'"'+ (item.code==code?'selected':'') +'>'+ item.name +'</option>');
    }
  })
}

function data_subdistrict(code){
    var name;
    $.each(subdistrict,function(index,item){
        if(item.code==code){
            name=item.name;
        }
    });
    return name;
}


function select_district(code, id, province) {
    $('#' + id).empty().append('<option value="NULL">เลือกอำเภอ</option>');
    $.each(district_v2, function (index, item) {
        if (item.province_id == province) {
            $('#' + id).append('<option value="' + item.code + '"' + (item.code == code ? 'selected' : '') + '>' + item.name + '</option>');
        }
    })

}

function select_province(code, id) {
    $('#' + id).empty().append('<option value="NULL">เลือกจังหวัด</option>');
    $.each(provinces, function (index, item) {
        $('#' + id).append('<option value="' + item.code + '"' + (item.code == code ? 'selected' : '') + '>' + item.name + '</option>');
    })
}

function data_province(code) {
    var name;
    $.each(provinces, function (index, item) {
        if (item.code == code) {
            name = item.name
        }
    })
    return name;
}

function select_subdistrict_v2(code, id, district) {
   // console.log(district);
    $('#' + id).empty().append('<option value="all">ทั้งหมด</option>');
   
    $.each(subdistrict, function(index, item) {
        if (item.district_id == district) {
            $('#' + id).append('<option value="' + item.code + '"' + (item.code == code ? 'selected' : '') + '>' + item.name + '</option>');
        }
    })
}


